    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void LegacyAttributeHook_CanFlushPreviouslyBufferedText ()
    {
        FlushingAttributeOutput output = new ();
        OutputBufferImpl buffer = new ();
        buffer.SetSize (2, 1);
        buffer.CurrentAttribute = new (new Color (1, 0, 0), Color.Black);
        buffer.AddStr ("A");
        buffer.CurrentAttribute = new (new Color (2, 0, 0), Color.Black);
        buffer.AddStr ("B");

        output.Write (buffer);

        Assert.Equal (["attribute:1", "text:A", "attribute:2", "text:B"], output.Events);
    }

    // Claude - Opus 5.5
    [Fact]
    public void LegacyAttributeHook_PerCellColors_AllocationIsLinear ()
    {
        AppendingAttributeOutput output = new ();
        OutputBufferImpl buffer = new ();
        buffer.SetSize (200, 50);

        for (var row = 0; row < 50; row++)
        {
            buffer.Move (0, row);

            for (var col = 0; col < 200; col++)
            {
                buffer.CurrentAttribute = new (new Color (col, row, (col + row) % 256), Color.Black);
                buffer.AddStr ("x");
            }
        }

        long before = GC.GetAllocatedBytesForCurrentThread ();
        output.Write (buffer);
        long allocated = GC.GetAllocatedBytesForCurrentThread () - before;

        // A quadratic hook path re-copied the pending frame on every attribute change (hundreds of MB here).
        Assert.InRange (allocated, 0, 16 * 1024 * 1024);
        Assert.Equal (10_000, output.AttributeCalls);
    }

