    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void FailedUnixFrame_CanBeRetriedWithoutRedrawingBuffer ()
    {
        bool fail = true;
        List<string> writes = [];
        AnsiOutput output = new (bytes =>
        {
            if (fail)
            {
                fail = false;
                return false;
            }

            writes.Add (Encoding.UTF8.GetString (bytes));
            return true;
        });
        OutputBufferImpl buffer = new ();
        buffer.SetSize (1, 1);
        buffer.AddStr ("X");

        Assert.Throws<IOException> (() => output.Write (buffer));
        Assert.True (buffer.DirtyLines [0]);
        Assert.True (buffer.Contents! [0, 0].IsDirty);

        output.Write (buffer);

        Assert.Single (writes);
        Assert.Contains ("X", writes [0]);
        Assert.False (buffer.DirtyLines [0]);
    }

