    // CoPilot - GPT-6 (generated by Codex)
    [Theory]
    [InlineData (false)]
    [InlineData (true)]
    public void FailedFrame_RetriesRasterAndSixel (bool sourceCrop)
    {
        bool fail = true;
        List<string> writes = [];
        AnsiOutput output = new (bytes =>
        {
            if (fail)
            {
                fail = false;
                return false;
            }

            writes.Add (Encoding.UTF8.GetString (bytes));
            return true;
        }) { UseKittyGraphics = true };
        OutputBufferImpl buffer = new ();
        buffer.SetSize (2, 1);
        RasterImageCommand image = new ()
        {
            Id = "retry-image",
            Pixels = new Color [1, 1] { { new (255, 0, 0) } },
            DestinationCells = new (1, 0, 1, 1),
            SourceRect = sourceCrop ? new Rectangle (0, 0, 1, 1) : null
        };
        buffer.AddRasterImage (image);
        SixelToRender sixel = new () { SixelData = "\u001bPq#0~\u001b\\", ScreenPosition = new (0, 0) };
        output.GetSixels ().Enqueue (sixel);

        Assert.Throws<IOException> (() => output.Write (buffer));
        Assert.True (image.IsDirty);
        Assert.True (sixel.IsDirty);
        output.Write (buffer);

        string actual = string.Concat (writes);
        Assert.Contains (sourceCrop ? "a=t" : "a=T", actual);
        Assert.Contains (sixel.SixelData, actual);
        Assert.Contains ("a=d", actual);
        Assert.False (image.IsDirty);
        Assert.False (sixel.IsDirty);
    }

