        buffer.AddStr ("中");
        bool [,] dirty = new bool [3, 4];
        for (int row = 0; row < 3; row++)
        {
            for (int col = 0; col < 4; col++)
            {
                dirty [row, col] = buffer.Contents! [row, col].IsDirty;
