    // CoPilot - GPT-6 (generated by Codex)
    [Theory]
    [InlineData (128 * 1024, 16)]
    [InlineData (1024 * 1024, 3)]
    public void ManySixels_BoundStagingAndKeepOrder (int payloadSize, int count)
    {
        int writes = 0;
        int total = 0;
        int largest = 0;
        AnsiOutput output = new (bytes =>
        {
            writes++;
            total += bytes.Length;
            largest = Math.Max (largest, bytes.Length);
            return true;
        }) { CaptureOutput = false };
        OutputBufferImpl buffer = new ();
        buffer.SetSize (1, 1);
        for (int index = 0; index < count; index++)
        {
            output.GetSixels ().Enqueue (new SixelToRender
            {
                SixelData = new string ('q', payloadSize),
                ScreenPosition = new (0, 0)
            });
        }

        output.Write (buffer);

        Assert.True (writes >= 3);
        Assert.InRange (largest, 1, Utf8Buffer.RetainedCapacityLimit);
        Assert.True (total > 2 * 1024 * 1024);
        Assert.InRange (output.RetainedWriteBufferBytes, 0, Utf8Buffer.RetainedCapacityLimit * 2);
    }

