    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void FailedStyledLinkedFrame_RetryResetsTerminalStateAndCaptureMatchesBytes ()
    {
        int attempts = 0;
        List<string> writes = [];
        AnsiOutput output = new (bytes =>
        {
