    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void WindowsVT_PartialWrite_DoesNotAllocateTailArray ()
    {
        int calls = 0;
        WindowsVTOutputHelper helper = new ((ReadOnlySpan<byte> _, out uint written, out int error) =>
        {
            calls++;
            written = 1;
            error = 0;
            return true;
        });
        byte [] backing = new byte [1024 * 1024];
        helper.Write (backing.AsSpan (0, 2));
        calls = 0;
        long before = GC.GetAllocatedBytesForCurrentThread ();

        helper.Write (backing.AsSpan (0, 2));

        long allocated = GC.GetAllocatedBytesForCurrentThread () - before;
        Assert.Equal (2, calls);
        Assert.InRange (allocated, 0, 128);
    }

    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void StreamingFrame_LateFailure_RetriesTextAndLargeSixel ()
    {
        int attempts = 0;
        int textWrites = 0;
        int imageBytes = 0;
        AnsiOutput output = new (bytes =>
        {
            if (++attempts == 2)
            {
                return false;
            }

            if (bytes.IndexOf ((byte)'X') >= 0) textWrites++;
            foreach (byte value in bytes)
            {
                if (value == (byte)'q') imageBytes++;
            }
            return true;
        }) { CaptureOutput = false };
        OutputBufferImpl buffer = new ();
        buffer.SetSize (1, 1);
        buffer.AddStr ("X");
        SixelToRender sixel = new ()
        {
            SixelData = new string ('q', 2 * Utf8Buffer.RetainedCapacityLimit),
            ScreenPosition = new (0, 0)
        };
        output.GetSixels ().Enqueue (sixel);

        Assert.Throws<IOException> (() => output.Write (buffer));
        Assert.Equal (1, textWrites);
        Assert.True (buffer.Contents! [0, 0].IsDirty);
        Assert.True (sixel.IsDirty);
        int previouslyWrittenImageBytes = imageBytes;
        Assert.True (previouslyWrittenImageBytes > 0);
        output.Write (buffer);

        Assert.Equal (2, textWrites);
        Assert.Equal (previouslyWrittenImageBytes + sixel.SixelData.Length, imageBytes);
        Assert.False (buffer.DirtyLines [0]);
        Assert.False (sixel.IsDirty);
    }

    private sealed class PhysicalAttributeOutput : AnsiOutput
    {
        private readonly List<string> _events;

        public PhysicalAttributeOutput (List<string> events) : base (bytes =>
        {
            string text = Encoding.UTF8.GetString (bytes);
            if (text.Contains ('A')) events.Add ("text:A");
            if (text.Contains ('B')) events.Add ("text:B");
            return true;
        }) => _events = events;

        protected override void AppendOrWriteAttribute (StringBuilder output,
                                                        Terminal.Gui.Drawing.Attribute attr,
                                                        TextStyle redrawTextStyle)
        {
            Write (output);
            output.Clear ();
            _events.Add ($"attribute:{attr.Foreground.R}");
        }
    }

    private sealed class LegacyAnsiOutput : AnsiOutput
    {
        public StringBuilder Written { get; } = new ();
        protected override void Write (StringBuilder output) => Written.Append (output);
    }

    private sealed class LegacyNetOutput : NetOutput
    {
        public StringBuilder Written { get; } = new ();
        protected override void Write (StringBuilder output) => Written.Append (output);
    }

    private class StringOutput : OutputBase
    {
        public StringBuilder Written { get; } = new ();

        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;

        protected override void Write (StringBuilder output) => Written.Append (output);
    }

    private sealed class AppendingAttributeOutput : OutputBase
    {
        public int AttributeCalls { get; private set; }

        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;

        protected override void Write (StringBuilder output) { }

        protected override void AppendOrWriteAttribute (StringBuilder output,
                                                        Terminal.Gui.Drawing.Attribute attr,
                                                        TextStyle redrawTextStyle)
        {
            AttributeCalls++;
            output.Append ("\u001b[38;2;1;2;3m");
        }
    }

    private sealed class SplitSurrogateOutput : StringOutput
    {
        protected override void AppendOrWriteAttribute (StringBuilder output,
                                                        Terminal.Gui.Drawing.Attribute attr,
                                                        TextStyle redrawTextStyle)
        {
            output.Append ('a', 15);
            output.Append ('\ud83d');
            output.Append ('\ude00');
        }
    }

    private sealed class FlushingAttributeOutput : OutputBase
    {
        public List<string> Events { get; } = [];

        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;

        protected override void Write (StringBuilder output)
        {
            if (output.Length > 0)
            {
                Events.Add ($"text:{output}");
            }
        }

        protected override void AppendOrWriteAttribute (StringBuilder output,
                                                        Terminal.Gui.Drawing.Attribute attr,
                                                        TextStyle redrawTextStyle)
        {
            Write (output);
            output.Clear ();
            Events.Add ($"attribute:{attr.Foreground.R}");
        }
    }
}
